-- =========================================================
-- STEP Obras | Patch v17
-- Tabela detalhada de custos + carga da planilha Melhorias base STEP 25-05-26.xlsx
-- Este script NÃO altera fotos e NÃO altera posições do mapa.
-- Ele cria/atualiza somente a tabela de custos e recalcula o campo cost dos itens vinculados.
-- =========================================================

begin;

create extension if not exists pgcrypto;

create table if not exists public.step_obras_costs (
  id bigserial primary key,
  row_key text not null unique,
  item_id text references public.step_obras_items(id) on delete set null,
  setor text,
  cotacao text,
  data_cotacao date,
  pedido text,
  data_pedido date,
  fornecedor text,
  produto text,
  quantidade numeric(14,3) default 0,
  valor numeric(14,2) default 0,
  origem text,
  status_compra text default 'Não informado',
  disciplina text,
  observacao text,
  source text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_step_obras_costs_item_id on public.step_obras_costs(item_id);
create index if not exists idx_step_obras_costs_status on public.step_obras_costs(status_compra);
create index if not exists idx_step_obras_costs_setor on public.step_obras_costs(setor);
create index if not exists idx_step_obras_costs_pedido on public.step_obras_costs(pedido);

alter table public.step_obras_costs enable row level security;

drop policy if exists "step_obras_costs_select" on public.step_obras_costs;
create policy "step_obras_costs_select"
on public.step_obras_costs for select
to anon, authenticated
using (true);

delete from public.step_obras_costs;

on conflict (row_key) do update set
  item_id=excluded.item_id,
  setor=excluded.setor,
  cotacao=excluded.cotacao,
  data_cotacao=excluded.data_cotacao,
  pedido=excluded.pedido,
  data_pedido=excluded.data_pedido,
  fornecedor=excluded.fornecedor,
  produto=excluded.produto,
  quantidade=excluded.quantidade,
  valor=excluded.valor,
  origem=excluded.origem,
  status_compra=excluded.status_compra,
  disciplina=excluded.disciplina,
  source=excluded.source,
  updated_at=now();

-- Recalcula custo total vinculado por item da planta sem mexer em fotos/mapa/observações.
with totals as (
  select item_id, sum(valor)::numeric(14,2) as total
  from public.step_obras_costs
  where item_id is not null
  group by item_id
)
update public.step_obras_items i
set cost = totals.total,
    updated_at = now()
from totals
where i.id = totals.item_id;

values (
  'costs_import',
  jsonb_build_object(
    'source', 'Melhorias base STEP 25-05-26.xlsx',
    'rows', 311,
    'total', 23281362.25,
    'importedAt', now()
  ),
  now()
)
on conflict (key) do update set value=excluded.value, updated_at=now();

commit;
